cards.primary:
{% set cat = states('sensor.family_room_downstairs_last_cat') %}
{% set t = states('sensor.family_room_downstairs_last_visit') %}
{% if cat not in ['unknown','unavailable','none','','-'] %}{{ cat }}{% if t not in ['unknown','unavailable','none','','-'] %} · {{ t }}{% endif %}
{% elif t not in ['unknown','unavailable','none','','-'] %}{{ t }}
{% else %}—{% endif %}

cards.secondary:
{% set h = states('sensor.family_room_downstairs_litter_age_hours') %}
{% if h in ['unknown','unavailable','none',''] %}Litter: press Refilled litter
{% else %}{% set hrs = h|float(0) %}Litter: {% if hrs < 24 %}{{ hrs|round(0)|int }}h{% else %}{{ (hrs/24)|round(1) }}d{% endif %}{% endif %}
·
{% set bag = states('sensor.family_room_downstairs_bag_age_hours') %}
{% if bag in ['unknown','unavailable','none',''] %}Bag age: unknown
{% else %}{% set hrs = bag|float(0) %}Bag age: {% if hrs < 24 %}{{ hrs|round(0)|int }}h{% else %}{{ (hrs/24)|round(1) }}d{% endif %}{% endif %}
· Cleaned {{ states('sensor.family_room_downstairs_last_cleaned') }}

cards.icon_color:
{% set sev = state_attr('sensor.family_room_downstairs_toilet_status','severity') %}
{% if sev == 'critical' or is_state('binary_sensor.family_room_downstairs_needs_cleaning','on') %}red
{% elif is_state('binary_sensor.family_room_downstairs_trash_door_jammed','on') or states('sensor.family_room_downstairs_bag_status') in ['Bag full','No Bag'] %}red
{% elif is_state('binary_sensor.family_room_downstairs_cat_inside','on') or sev == 'occupied' %}green
{% elif sev == 'attention' %}orange
{% else %}blue{% endif %}

card_mod.style:
ha-card {
  --chip-background: transparent;
  --chip-border-width: 0;
  --chip-box-shadow: none;
  --chip-height: 42px;
  background: none !important;
  box-shadow: none !important;
  border: none !important;
}
.chip-container {
  display: grid !important;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  width: 100%;
  gap: 8px;
}
mushroom-chip {
  width: 100% !important;
  justify-content: flex-start !important;
}

